                            const axisKeyX = idx === 1 ? 'xaxis' : 'xaxis' + idx;
                            const axisKeyY = idx === 1 ? 'yaxis' : 'yaxis' + idx;
                            const cell = (focusGrid[r] && focusGrid[r][c]) ? focusGrid[r][c] : { pointsByWavelength: [] };
